्मभूर्भुवः स्वरोम्।\"]},{\"label\":\"स्त्रीको निम्ति\",\"lines\":[\"ॐ श्रीं प्रकृतितत्वाय नमः\"]}]',0,23,'2026-09-27 10:04:04'),(25,'mantra','राशि मन्त्र','tal-rashaka-manatara','तुला राशिको मन्त्र',NULL,NULL,'[{\"label\":\"स्त्री-पुरुष दुवैको निम्ति\",\"lines\":[\"ॐ श्रीं रामचन्दाय नमः\"]},{\"label\":\"पुरुषको निम्ति\",\"lines\":[\"ॐ ह्रीं वामदेवाय नमः। ब्रह्मभूर्भुवः स्वरोम्।\"]},{\"label\":\"स्त्रीको निम्ति\",\"lines\":[\"ॐ श्रीं जगतामधीश्वर्यै नमः\"]}]',0,24,'2026-09-27 10:04:04'),(26,'mantra','राशि मन्त्र','vashacaka-rashaka-manatara','वृश्चिक राशिको मन्त्र',NULL,NULL,'[{\"label\":\"स्त्री-पुरुष दुवैको निम्ति\",\"lines\":[\"ॐ क्रीं जानकीरामाय नमः\"]},{\"label\":\"पुरुषको निम्ति\",\"lines\":[\"ॐ वरदाय नमः। ब्रह्मभूर्भुवः स्वरोम्।\"]},{\"label\":\"स्त्रीको निम्ति\",\"lines\":[\"ॐ क्षं वसुदायै नमः\"]}]',0,25,'2026-09-27 10:04:04'),(27,'mantra','राशि मन्त्र','thhana-rashaka-manatara','धनु राशिको मन्त्र',NULL,NULL,'[{\"label\":\"स्त्री-पुरुष दुवैको निम्ति\",\"lines\":[\"ॐ क्रीं भगवते नमः\"]},{\"label\":\"पुरुषको निम्ति\",\"lines\":[\"ॐ उं त्रिपुरान्तकाय नमः। ब्रह्मभूर्भुवः स्वरोम्।\"]},{\"label\":\"स्त्रीको निम्ति\",\"lines\":[\"ॐ हं हंसप्रभायै नमः\"]}]',0,26,'2026-09-27 10:04:04'),(28,'mantra','राशि मन्त्र','makara-rashaka-manatara','मकर राशिको मन्त्र',NULL,NULL,'[{\"label\":\"स्त्री-पुरुष दुवैको निम्ति\",\"lines\":[\"ॐ श्रीवत्साय उपेन्द्राय नमः\"]},{\"label\":\"पुरुषको निम्ति\",\"lines\":[\"ॐ ऋं त्रिविक्रमाय नमः। ब्रह्मभूर्भुवः स्वरोम्।\"]},{\"label\":\"स्त्रीको निम्ति\",\"lines\":[\"ॐ श्रीं ध्रुवा प्राणशक्त्यै नमः\"]}]',0,27,'2026-09-27 10:04:04'),(29,'mantra','राशि मन्त्र','kamabha-rashaka-manatara','कुम्भ राशिको मन्त्र',NULL,NULL,'[{\"label\":\"स्त्री-पुरुष दुवैको निम्ति\",\"lines\":[\"ॐ गोपालगोविन्दाय नमः\"]},{\"label\":\"पुरुषको निम्ति\",\"lines\":[\"ॐ ह्रीं श्रीकण्ठाय नमः। ब्रह्मभूर्भुवः स्वरोम्।\"]},{\"label\":\"स्त्रीको निम्ति\",\"lines\":[\"ॐ क्षौ ईशानाय नमः\"]}]',0,28,'2026-09-27 10:04:04'),(30,'mantra','राशि मन्त्र','mana-rashaka-manatara','मीन राशिको मन्त्र',NULL,NULL,'[{\"label\":\"स्त्री-पुरुष दुवैको निम्ति\",\"lines\":[\"ॐ श्रीं ह्रीं श्रीं क्रीं रथाङ्गचक्राय नमः\"]},{\"label\":\"पुरुषको निम्ति\",\"lines\":[\"ॐ क्षौं श्रीमुखाय नमः। ब्रह्मभूर्भुवः स्वरोम्।\"]},{\"label\":\"स्त्रीको निम्ति\",\"lines\":[\"ॐ हंस सर्ववीजरूपायै नमः\"]}]',0,29,'2026-09-27 10:04:04'),(31,'mantra','विशेष मन्त्र','maha-matayajaya-manatara','महा मृत्युंजय मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ ह्रौं ॐ जूं सः भूर्भुवः स्वः\",\"ॐ त्र्यम्बकं यजामहे सुगन्धिं पुष्टिवर्द्धनम्।\",\"उर्वारुकमिव बन्धनान् मृत्योर्मुक्षीय मामृतात्॥\",\"ॐ स्वः भुवः भूः ॐ सः जूं ह्रौं ॐ\"]}]',0,30,'2026-09-27 10:04:04'),(32,'mantra','विशेष मन्त्र','shatara-nasha-garana-manatara','शत्रु नाश गर्ने मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ शिरो मे बगला पातु हृदयैकाक्षरी परा।\",\"ॐ ह्रीं ॐ मे ललाटे च बगलावैरिनाशिनी॥\",\"गदाहस्ता सदा पातु मुखं मे मोक्षदायिनी।\",\"वैरिजिह्वाधरा पातु कण्ठं मे बगलामुखी॥\"]}]',0,31,'2026-09-27 10:04:04'),(33,'mantra','विशेष मन्त्र','pata-raga-navaranae-manatara','पेट रोग निवारण मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ उदरं नाभिदेशं च पातु नित्यं परात्परा।\",\"परात्परतरा पातु मम गुह्यं सुरेश्वरी॥\"]}]',0,32,'2026-09-27 10:04:04'),(34,'mantra','विशेष मन्त्र','mathathama-vajaya-parapata-garana-manatara','मुद्दामा विजय प्राप्त गर्ने मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ हस्तौ चैव तथा पादौ पार्वती परिपातु मे।\",\"विवादे विषमे घोरे संग्रामे रिपुसंकटे॥\"]}]',0,33,'2026-09-27 10:04:04'),(35,'mantra','विशेष मन्त्र','shararaka-rakashha-garana-manatara','शरीरको रक्षा गर्ने मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ पीताम्बराधरा पातु सर्वाङ्गं शिवनर्तकी।\",\"श्रीविद्या समयं पातु मातङ्गी पूरिता शिवा॥\"]}]',0,34,'2026-09-27 10:04:04'),(36,'mantra','विशेष मन्त्र','paravaraka-rakashha-garana-manatara','परिवारको रक्षा गर्ने मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ पातु पुत्रं सतांश्चैव कलत्रं कालिका मम।\",\"पातु नित्यं भ्रातरं मे पितरं शूलिनी सदा॥\"]}]',0,35,'2026-09-27 10:04:04'),(37,'mantra','विशेष मन्त्र','shataraka-bthathhanasha-garana-manatara-1','शत्रुको बुद्धिनाश गर्ने मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ ह्रीं बगलामुखि सर्वदुष्टानां वाचं मुखं पदं\",\"स्तम्भय जिह्वां कीलय बुद्धिं नाशय ह्लीं ॐ स्वाहा॥\"]}]',0,36,'2026-09-27 10:04:04'),(38,'mantra','विशेष मन्त्र','shatara-mahata-garana-manatara','शत्रु मोहित गर्ने मन्त्र',NULL,NULL,'[{\"label\":\"आफ्नो कुरा मनाउने मन्त्र\",\"lines\":[\"राजानोऽप्यरयो मदान्धकरिणः सर्पा मृगेन्द्रादिकास्ते।\",\"वै यान्ति विमोहिता रिपुगणा लक्ष्मीः स्थिरा सर्वतः॥\",\"------------------------\",\"दुष्टोच्चाटनकारिणी जनमनः संमोहसंदायिनी।\",\"जिह्वां कीलय भैरवी विजयते ब्रह्माश्च विद्या परा॥\"]}]',0,37,'2026-09-27 10:04:04'),(39,'mantra','विशेष मन्त्र','shara-parapata-manatara','श्री प्राप्ति मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ मनसः काममाकूतिंवाचः सत्त्यमशीय।\",\"पशूनां रूपमन्नस्यरसोयशः श्रीः श्रयताम्॥\"]}]',0,38,'2026-09-27 10:04:04'),(40,'mantra','विशेष मन्त्र','kalsarapa-samasata-manatara-1','कालसर्प समस्त मन्त्र',NULL,NULL,'[{\"label\":\"काल मन्त्र\",\"lines\":[\"कार्षिरसि समुद्रस्य त्त्वाक्षित्त्याऽउन्नयामि।\",\"समापोऽअद्भिरग्मत समोषधीभिरोषधीः॥\"]},{\"label\":\"नाग मन्त्र\",\"lines\":[\"ॐ नमोऽस्तु सर्पेब्भ्यो ये(जे) के च पृथिवीमनु।\",\"ये(जे) अन्तरिक्षे ये(जे) दिवि तेब्भ्यः सर्पेब्भ्यो नमः॥\"]},{\"label\":\"मनसा मन्त्र\",\"lines\":[\"ॐ ह्रीं तत्कारिणी विषहारिणी विषरूपिणी\",\"विषं हन इन्द्रस्य वज्रेण नमः॥\"]},{\"label\":\"यम मन्त्र\",\"lines\":[\"ॐ यमायत्वा मखायत्वा सूर्य्यस्यत्वा तपसे देवस्यत्वा सवितामध्वा\",\"नक्तु पृथ्विया स गुँ स्पृशस्पाहि अर्चिरसि शोचिरसि तपोसी॥\"]},{\"label\":\"अघोर मन्त्र\",\"lines\":[\"ॐ अघोरेभ्योऽथ घोरेभ्यो घोर घोरतरेभ्यः।\",\"सर्वेभ्यः सर्वसर्पेब्भ्यो नमस्ते अस्तु रुद्ररूपेभ्यः॥\"]},{\"label\":\"राहु मन्त्र\",\"lines\":[\"ॐ कया नश्श्चित्रऽआभुवदूती सदावृधः सखा।\",\"कया शचिष्ठ्ठया वृता॥\"]},{\"label\":\"केतु मन्त्र\",\"lines\":[\"ॐ केतुं कृण्ण्वन्नकेतवे पेशो मर्याऽअपेशसे।\",\"समुषद्भिरजायथाः॥\"]},{\"label\":\"महा मृत्युंजय मन्त्र\",\"lines\":[\"ॐ ह्रौं ॐ जूं सः भूर्भुवः स्वः\",\"ॐ त्र्यम्बकं यजामहे सुगन्धिं पुष्टिवर्द्धनम्।\",\"उर्वारुकमिव बन्धनान् मृत्योर्मुक्षीय मामृतात्॥\",\"ॐ स्वः भुवः भूः ॐ सः जूं ह्रौं ॐ\"]}]',0,39,'2026-09-27 10:04:04'),(41,'mantra','विशेष मन्त्र','navanaga-nama-satatara','नवनाग नाम स्तोत्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"अनन्तं वासुकीं शेषं पद्मनाभञ्च कम्बलम्।\",\"शङ्पालं धार्तराष्ट्रं तक्षकं कालियं तथा॥\",\"एतानि नवनामानि नागानां च महात्मनां।\",\"सायङ्काले पठेत्रित्यं प्रातःकाले विशेषतः।\",\"तस्मै विषभयं नास्ति सर्वत्र विजयी भवेत्॥\"]}]',0,40,'2026-09-27 10:04:04'),(42,'mantra','विशेष मन्त्र','ganaesha-manatara-2','गणेश मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ रक्ष रक्ष गणाध्यक्ष रक्ष त्रैलोक्यरक्षक।\",\"भक्तानामभयं कर्त्ता त्राता भव भवार्णवात्॥\",\"द्वैमातुर कृपासिन्धो षाण्मातुराग्रज प्रभो।\",\"वरदस्त्वं वरं देहि वाञ्छितं वाञ्छितार्थद॥\",\"अनेन फलदानेन फलदोऽस्तु सदा मम॥\"]}]',0,41,'2026-09-27 10:04:04'),(43,'mantra','विशेष मन्त्र','paniacamakha-hanamana-manatara','पञ्चमुखी हनुमान मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ नमो हनुमते रुद्रावताराय, सर्व-शत्रु-संहारणाय,\",\"सर्व-रोग-हराय, सर्व-वशीकरणाय, राम-दूताय स्वाहा\"]}]',0,42,'2026-09-27 10:04:04'),(44,'mantra','विशेष मन्त्र','lkashhama-kabra-manatara','लक्ष्मी कुबेर मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ श्रीं ह्रीं क्लीं श्री सिद्ध लक्ष्मी कुबेराय नमः॥\"]}]',0,43,'2026-09-27 10:04:04'),(45,'mantra','विशेष मन्त्र','mahalkashhama-manatara-1','महालक्ष्मी मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ श्रीं हीं श्रीं कमले कमलालये प्रसीद प्रसीद\",\"ॐ श्रीं हीं श्रीं महालक्ष्म्यै नमः॥\"]}]',0,44,'2026-09-27 10:04:04'),(46,'mantra','विशेष मन्त्र','mal-sathathha-garana-manatara','माला सिद्धि गर्ने मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ऐं ह्रीं अक्षमालिकायै नमः\",\"ॐ मां माले महामाये सर्वशक्तिस्वरूपिणि।\",\"चतुर्वर्गस्त्वयि न्यस्तस्तस्मान्मे सिद्धिदा भव॥\",\"ॐ अविघ्नं कुरु माले त्वं गृह्णामि दक्षिणे करे।\",\"जपकाले च सिद्ध्यर्थं प्रसीद मम सिद्धये॥\"]}]',0,45,'2026-09-27 10:04:04'),(47,'mantra','विशेष मन्त्र','shakata-makata-parapata-manatara','शक्ति-मुक्ति प्राप्ति मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"त्वं वैष्णवी शक्तिरनन्तवीर्या\",\"विश्वस्य बीजं परमासि माया।\",\"सम्मोहितं देवि समस्तमेतत्\",\"त्वं वै प्रसन्ना भुवि मुक्तिहेतुः॥\"]}]',0,46,'2026-09-27 10:04:04'),(48,'mantra','विशेष मन्त्र','sakha-parapata-manatara','सुख प्राप्ति मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"सर्वेषामेव भूतानां सुखदं शान्तमव्ययम्‌।\",\"मृत्युञ्जयं महाकालं नमस्यामि शनैश्चरम्‌॥\"]}]',0,47,'2026-09-27 10:04:04'),(49,'mantra','विशेष मन्त्र','ananaparanae-manatara','अन्नपूर्णा मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"अन्नपूर्णे सदापूर्णे शङ्करप्राणवल्लभे।\",\"ज्ञानवैराग्यसिद्ध्यर्थं भिक्षां देहि च पार्वति॥\"]}]',0,48,'2026-09-27 10:04:04'),(50,'mantra','विशेष मन्त्र','mahalkashhama-manatara-3','महालक्ष्मी मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ श्रीं ह्रीं श्रीं कमले कमलालये प्रसीद प्रसीद ॐ श्रीं ह्रीं श्रीं महालक्ष्मयै नमः॥\"]}]',0,49,'2026-09-27 10:04:04'),(51,'mantra','विशेष मन्त्र','kabra-manatara','कुबेर मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ यक्षाय कुबेराय वैश्रवणाय धनधान्याधिपतये\",\"धनधान्यसमृद्धिं मे देहि दापय स्वाहा॥\"]}]',0,50,'2026-09-27 10:04:04'),(52,'mantra','विशेष मन्त्र','kabra-manatara-1','कुबेर मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ श्रीं ॐ ह्रीं श्रीं ॐ ह्रीं श्रीं क्लीं वित्तेश्वराय: नमः॥\"]}]',0,51,'2026-09-27 10:04:04'),(53,'mantra','विशेष मन्त्र','bhaya-nashaka-manatara','भय नाशक मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"सर्वस्वरूपे सर्वेशे सर्वशक्ति समन्विते।\",\"भयेभ्याहि नो देवि दुर्गे देवि नमोऽस्तु ते॥\",\"एतत्ते वदनं सौम्यं लोचनत्रयभूषितम्।\",\"पातु न: सर्वभीतिभ्य: कात्यायनि नमोऽस्तु ते॥\",\"ज्वालाकरालमत्युग्रमशेषासुरसूदनम्।\",\"त्रिशूलं पातु नो भीतेर्भद्रकालि नमोऽस्तु ते॥\"]}]',0,52,'2026-09-27 10:04:04'),(54,'mantra','विशेष मन्त्र','samapatata-parapata-manatara','सम्पत्ति प्राप्ति मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"आयुर्देहि धनं देहि विद्यां देहि महेश्वरि।\",\"समस्तमखिलां देहि देहि मे परमेश्वरि॥\"]}]',0,53,'2026-09-27 10:04:04'),(55,'mantra','विशेष मन्त्र','sanatana-parapata-manatara','सन्तान प्राप्ति मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"याचेऽहं पुत्रसन्तानं भवन्तं पद्मलोचन।\",\"देहि मे तनयं कृष्ण त्वामहं शरणं गतः॥\",\"देवकीसुत गोविन्द वासुदेव जगत्पते।\",\"देहि मे तनयं कृष्ण त्त्वमहं शरणङ्गत॥\",\"Note: सन्तान नभएकाले यो नित्य जप गर्नाले असल सन्तान प्राप्त हुन्छ।\"]}]',0,54,'2026-09-27 10:04:04'),(56,'mantra','विशेष मन्त्र','ananaparanae-manatara-1','अन्नपूर्णा मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"अन्नपूर्णे सदापूर्णे शङ्करप्राणवल्लभे।\",\"ज्ञानवैराग्यसिद्ध्यर्थं भिक्षां देहि च पार्वति॥\"]}]',0,55,'2026-09-27 10:04:04'),(57,'mantra','विशेष मन्त्र','kabra-thhanaparapata-manatara-1','कुबेर धनप्राप्ति मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ श्रीं ह्रीं क्लीं श्रीं क्लीं वित्तेश्वराय नमः॥\"]}]',0,56,'2026-09-27 10:04:04'),(58,'mantra','गणेश मन्त्र','ganaesha-manatara-1','गणेश मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ गणानान्त्वा गणपति गुङ् हवामहे\",\"प्प्रियाणान्त्वा प्रियपति गुङ् हवामहे\",\"निधीनान्त्वा निधिपति गुङ् हवामहे व्वसोमम।\",\"आहमजानि गर्ब्भधमा त्त्वमजासि गर्ब्भधम्॥\"]}]',0,57,'2026-09-27 10:04:04'),(59,'mantra','गणेश मन्त्र','ganaeshalii-pararathana-garana-manatara','गणेशलाई प्रार्थना गर्ने मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ वक्रतुण्ड महाकाय सूर्यकोटि समप्रभः।\",\"निर्विघ्नं कुरु मे देव सर्वकार्येषु सर्वदा॥\"]},{\"label\":\"अर्थः\",\"lines\":[\"टेढो मुहार भएका, स्थूल शरीर भएका, करोड सूर्यको समान तेज भएका हे गणनाथ! मेरा विघ्न बाधाहरू हटोस्।\"]}]',0,58,'2026-09-27 10:04:04'),(60,'mantra','गणेश मन्त्र','ganaesha-satata-shalka','गणेश स्तुति श्लोक',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"विघ्नेश्वराय वरदाय सुरप्रियाय लम्बोदराय \",\"सकलाय जगद्धितायं। \",\"नागाननाय श्रुतियज्ञविभूषिताय \",\"गौरीसुताय गणनाथ नमो नमस्ते॥ \",\"गजाननं भूतगणादिसेवितं \",\"कपित्थजम्बूफलचारु भक्षणम्ं। \",\"उमासुतं शोकविनाशकारकं नमामि \",\"विघ्नेश्वरपादपङ्कजम्॥ \",\"वक्रतुंड महाकाय, सूर्यकोटि समप्रभः।\",\"निर्विघ्नं कुरु मे देव सर्व कार्येषु सर्वदा॥\"]}]',0,59,'2026-09-27 10:04:04'),(61,'mantra','गणेश मन्त्र','ganaesha-manatara-3','गणेश मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ रक्ष रक्ष गणाध्यक्ष रक्ष त्रैलोक्यरक्षक।\",\"भक्तानामभयं कर्त्ता त्राता भव भवार्णवात्॥\",\"द्वैमातुर कृपासिन्धो षाण्मातुराग्रज प्रभो।\",\"वरदस्त्वं वरं देहि वाञ्छितं वाञ्छितार्थद॥\",\"अनेन फलदानेन फलदोऽस्तु सदा मम॥\"]}]',0,60,'2026-09-27 10:04:04'),(62,'mantra','गणेश मन्त्र','ganaesha-pararathana-1','गणेश प्रार्थना',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"विघ्नेश्वराय वरदाय सुरप्रियाय\",\"लम्बोदराय सकलाय जगद्धिताय। \",\"नागाननाय श्रुतियज्ञविभूषिताय\",\"गौरीसुताय गणनाथ! नमो नमस्ते॥\",\"भक्तार्तिनाशनपराय गणेश्वराय\",\"सर्वेश्वराय शुभदाय सुरेश्वराय।\",\"विद्याधराय विकटाय च वामनाय\",\"भक्तप्रसन्नवरदाय नमो नमस्ते॥\",\"लम्बोदर! नमस्तुभ्यं सततं मोदकप्रिय! \",\"निर्विघ्नं कुरु मे देव! सर्वकार्येषु सर्वदा॥\",\"त्वां विघ्नशत्रुदलनेति च सुन्दरेति\",\"भक्तप्रियेति सुखदेति फलप्रदेति। \",\"विद्याप्रदेत्यघहरेति च ये स्तुवन्ति\",\"तेभ्योगणेश! वरदो भव नित्यमेव॥\",\"गणेशपूजने कर्म यन्यूनमधिकं कृतम्। \",\"तेन सर्वेण सर्वात्मा प्रसन्नोऽस्तु सदा मम॥\"]}]',0,61,'2026-09-27 10:04:04'),(63,'mantra','गणेश मन्त्र','ganaesha-manatara-4','गणेश मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"श्री गणेशाय नमः\",\"ॐ गं गणपतये नमो नमः\",\"श्री सिद्धिविनायक नमो नमः\",\"अष्टविनायक नमो नमः\",\"गणपती बाप्पा मोरया\"]}]',0,62,'2026-09-27 10:04:04'),(64,'mantra','देवी मन्त्र','mahalkashhama-manatara','महालक्ष्मी मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ भूः भुर्वः स्वः ॐ महालक्षम्यै च विद्महे सर्वशक्त्यै च धीमही तन्नोलक्ष्मी प्रचोदयात्॥\"]}]',0,63,'2026-09-27 10:04:04'),(65,'mantra','देवी मन्त्र','bgalmakha-manatara','बगलामुखी मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ शिरो मे बगला पातु हृदयैकाक्षरी परा।\",\"ॐ ह्रीं ॐ मे ललाटे च बगलावैरिनाशिनी॥\",\"गदाहस्ता सदा पातु मुखं मे मोक्षदायिनी।\",\"वैरिजिह्वाधरा पातु कण्ठं मे बगलामुखी॥\",\"-----------------------------\",\"ॐ जिह्वाग्रमादाय करेण देवीं\",\"वामेन शत्रुं परिपीडयन्तीम्।\",\"गदाभिघातेन च दक्षिणेन\",\"पीताम्बराख्यां द्विभुजां भजामि॥\"]}]',0,64,'2026-09-27 10:04:04'),(66,'mantra','देवी मन्त्र','thakha-nasha-garana-thava-pararathana','दुःख नाश गर्न देवी प्रार्थना',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ मातर्भैरवि भद्रकालि विजय बाराहि विश्वाश्रये।\",\"श्रीविद्ये समये महेश बगले कामक्षि वामे रमे॥\",\"मातंगि त्रिपुरे परात्परतरे स्वर्गापवर्गप्रदे।\",\"दासोऽहं शरणागतः करुणया विश्वेश्वरि त्राहि माम्॥\"]}]',0,65,'2026-09-27 10:04:04'),(67,'mantra','देवी मन्त्र','shataraka-bthathhanasha-garana-manatara','शत्रुको बुद्धिनाश गर्ने मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ ह्रीं बगलामुखि सर्वदुष्टानां वाचं मुखं पदं\",\"स्तम्भय जिह्वां कीलय बुद्धिं नाशय ह्लीं ॐ स्वाहा॥\"]}]',0,66,'2026-09-27 10:04:04'),(68,'mantra','देवी मन्त्र','samasayabta-makata-pauna-manatara','समस्याबाट मुक्ति पाउने मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ मातः श्रीबगलेति नाम ललितं यस्यास्ति जन्तोर्मुखे।\",\"त्वन्नामग्रहणेन संसदि मुखस्तम्भो भवेद्वादिनाम्॥\"]}]',0,67,'2026-09-27 10:04:04'),(69,'mantra','देवी मन्त्र','sashal-sharamata-parapata-manatara','सुशील श्रीमती प्राप्त मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"अभार्यों लभते भार्यां विनीतां सुसुतां सतीम्।\",\"सुशीलां सुन्दरीं रम्यामतिसुप्रियवादिनीम्॥\"]}]',0,68,'2026-09-27 10:04:04'),(70,'mantra','देवी मन्त्र','mahalkashhama-manatara-2','महालक्ष्मी मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ श्रीं हीं श्रीं कमले कमलालये प्रसीद प्रसीद\",\"ॐ श्रीं हीं श्रीं महालक्ष्म्यै नमः॥\"]}]',0,69,'2026-09-27 10:04:04'),(71,'mantra','देवी मन्त्र','lkashhama-gayatara-manatara','लक्ष्मी गायत्री मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ श्री महालक्ष्म्यै च विद्यहे विष्णु पत्न्यै\",\"च धीमहि तन्नो लक्ष्मी प्रचोदयात्॥\"]}]',0,70,'2026-09-27 10:04:04'),(72,'mantra','देवी मन्त्र','tharaga-manatara','दुर्गा मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"सर्व मंगल मांगल्ये शिवे सर्वार्थ साधिके।\",\"शरण्ये त्रयम्बके गौरी नारायणी नमोस्तुते॥\"]}]',0,71,'2026-09-27 10:04:04'),(73,'mantra','देवी मन्त्र','kal-manatara-2','काली मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"ॐ जयन्ती मंगला काली भद्रकाली कपालिनी\",\"दुर्गा क्षमा शिवा धात्री स्वहा स्वधा नमोऽस्तु‍ते॥\"]}]',0,72,'2026-09-27 10:04:04'),(74,'mantra','देवी मन्त्र','papa-nashaka-manatara','पाप नाशक मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"हिनस्ति दैत्यतेजांसि स्वनेनापूर्य या जगत्।\",\"सा घण्टा पातु नो देवि पापेभ्योऽन: सुतानिव॥\"]}]',0,73,'2026-09-27 10:04:04'),(75,'mantra','देवी मन्त्र','aaragaya-ra-sabhagaya-parapata-manatara','आरोग्य र सौभाग्य प्राप्ति मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"देहि सौभाग्यमारोग्यं देहि मे परमं सुखम्।\",\"रूपं देहि जयं देहि यशो देहि द्विषो जहि॥\"]}]',0,74,'2026-09-27 10:04:04'),(76,'mantra','देवी मन्त्र','parasananata-parapata-manatara','प्रसन्नता प्राप्ति मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"प्रणतानां प्रसीद त्वं देवि विश्वार्तिहारिणि।\",\"त्रैलोक्यवासिनामीडये लोकानां वरदा भव॥\"]}]',0,75,'2026-09-27 10:04:04'),(77,'mantra','देवी मन्त्र','shakata-parapata-manatara','शक्ति प्राप्ति मन्त्र',NULL,NULL,'[{\"label\":\"\",\"lines\":[\"सृष्टिस्थितिविनाशानां शक्ति भूते सनातनि।\",\"गुणाश्रये गुणमये नारायणि नमोऽस्तु ते॥\"]}]',0,76,'2026-09-27 10:04:04'),(78,'mantra','गायत्री मन्त्र','brahamanae-gayatara-manatara-1','ब्राह्मण गायत्री मन्त्र',NULL,NULL,'[{\"label\":\"आचमन मन्त्र\",\"lines\":[\"ॐ केशवाय नमः\",\"ॐ नारायणाय नमः\",\"ॐ माधवाय नमः\",\"ॐ गोविन्दाय नमः (भनी हात पखाल्नु पर्छ)\"]},{\"label\":\"गायत्री मन्त्र\",\"lines\":[\"ॐ भूर्भुवः स्वः तत्सवितुर्वरेण्यम् भर्गो देवस्यः\",\"धीमहि धियो यो नः प्रचोदयात्॥\"]}]',0,77,'2026-09-27 10:04:04'),(79,'mantra','गायत्री मन्त्र','brahamanae-gayatara-manatara','ब्राह्मणी गायत्री मन्त्र',NULL,NULL,'[{\"label\":\"आचमन मन्त्र\",\"lines\":[\"श्री आत्मतत्वाय नमः\",\"श्री विद्या तत्वाय नमः\",\"श्री शिवतत्वाय नमः\"]},{\"label\":\"गायत्री मन्त्र\",\"lines\":[\"श्री कात्यायन्यै च विद्महे वरप्रदायै धीमहि।\",\"तन्नो देवी प्रचोदयात्॥\"]}]',0,78,'2026-09-27 10:04:04'),(80,'mantra','गायत्री मन्त्र','kashhataraya-gayat