नवांछित फल पाया॥\"]}]',0,41,'2026-09-27 10:04:05'),(358,'aarati','आरती','shavaratara-aarata','शिवरात्रि आरती','public/img/mantra/1778039459_image.png',NULL,'[{\"label\":\"\",\"lines\":[\"आ गई महाशिवरात्रि पधारो शंकर जी।\",\"हो पधारो शंकर जी॥\"]},{\"label\":\"\",\"lines\":[\"आरती उतारें पार उतारो शंकर जी।\",\"हो उतारो शंकर जी॥\"]},{\"label\":\"\",\"lines\":[\"तुम नयन नयन में हो मन मन में धाम तेरा\",\"हे नीलकंठ है कंठ कंठ में नाम तेरा\"]},{\"label\":\"\",\"lines\":[\"हो देवो के देव जगत के प्यारे शंकर जी\",\"तुम राज महल में तुम्ही भिखारी के घर में\"]},{\"label\":\"\",\"lines\":[\"धरती पर तेरा चरन मुकुट है अम्बर में\",\"संसार तुम्हारा एक हमारे शंकर जी\"]},{\"label\":\"\",\"lines\":[\"तुम दुनिया बसाकर भस्म रमाने वाले हो\",\"पापी के भी रखवाले भोले भाले हो\"]},{\"label\":\"\",\"lines\":[\"दुनिया में भी दो दिन तो गुजरो शंकर जी\",\"क्या भेंट चढ़ाये तन मैला घर सूना है\"]},{\"label\":\"\",\"lines\":[\"ले लो आंसू के गंगा जल का नमूना है\",\"आ करके नयन में चरण पखारो शंकर जी।\"]}]',0,42,'2026-09-27 10:04:05'),(359,'aarati','आरती','ananaparanae-thava-aarata','अन्नपूर्णा देवी आरती','public/img/mantra/1778039463_image.png',NULL,'[{\"label\":\"\",\"lines\":[\"बारम्बार प्रणाम मैया बारम्बार प्रणाम\",\"जो नहीं ध्यावे तुम्हें अमिबके,\",\"कहां उसे विश्राम।\"]},{\"label\":\"\",\"lines\":[\"अन्नपूर्णा देवी नाम तिहारो,\",\"लेत होत सब काम॥\"]},{\"label\":\"\",\"lines\":[\"प्रलय युगान्तर और जन्मान्तर,\",\"कालान्तर तक नाम।\"]},{\"label\":\"\",\"lines\":[\"सुर सुरों की रचना करती,\",\"कहाँ कृष्ण कहं राम॥\"]},{\"label\":\"\",\"lines\":[\"चूमहि चरण चतुर चतुरानन,\",\"चारू चक्रधर श्याम।\"]},{\"label\":\"\",\"lines\":[\"चन्द्र चूड़ चन्द्रानन चाकर,\",\"शोभा लखहि ललाम॥\"]},{\"label\":\"\",\"lines\":[\"देवी देव। दयनीय दशा में,\",\"दया दया तब जाम।\"]},{\"label\":\"\",\"lines\":[\"त्राहि-त्राहि शरणागत वत्सल,\",\"शरणरूप तब धाम॥\"]},{\"label\":\"\",\"lines\":[\"श्री ह्रीं श्रद्धा भी ऐ विधा,\",\"श्री कलीं कमला काम।\"]},{\"label\":\"\",\"lines\":[\"कानित भ्रांतिमयी कांतिशांति,\",\"सयीवर दे तू निष्काम॥\"]}]',0,43,'2026-09-27 10:04:05'),(360,'aarati','आरती','saii-bb-aarata','साई बाबा आरती','public/img/mantra/1778039467_image.png',NULL,'[{\"label\":\"\",\"lines\":[\"आरती श्री साईं गुरुवर की।\",\"परमानन्द सदा सुरवर की॥\"]},{\"label\":\"\",\"lines\":[\"जा की कृपा विपुल सुखकारी।\",\"दुःख, शोक, संकट, भयहारी॥\"]},{\"label\":\"\",\"lines\":[\"शिरडी में अवतार रचाया।\",\"चमत्कार से तत्व दिखाया॥\"]},{\"label\":\"\",\"lines\":[\"कितने भक्त चरण पर आये।\",\"वे सुख शान्ति चिरंतन पाये॥\"]},{\"label\":\"\",\"lines\":[\"भाव धरै जो मन में जैसा।\",\"पावत अनुभव वो ही वैसा॥\"]},{\"label\":\"\",\"lines\":[\"गुरु की उदी लगावे तन को।\",\"समाधान लाभत उस मन को॥\"]},{\"label\":\"\",\"lines\":[\"साईं नाम सदा जो गावे।\",\"सो फल जग में शाश्वत पावे॥\"]},{\"label\":\"\",\"lines\":[\"गुरुवासर करि पूजा-सेवा।\",\"उस पर कृपा करत गुरुदेवा॥\"]},{\"label\":\"\",\"lines\":[\"राम, कृष्ण, हनुमान रूप में।\",\"दे दर्शन, जानत जो मन में॥\"]},{\"label\":\"\",\"lines\":[\"विविध धर्म के सेवक आते।\",\"दर्शन कर इच्छित फल पाते॥\"]},{\"label\":\"\",\"lines\":[\"जै बोलो साईं बाबा की।\",\"जो बोलो अवधूत गुरु की॥\"]},{\"label\":\"\",\"lines\":[\"\'साईंदास\' आरती को गावे।\",\"घर में बसि सुख, मंगल पावे॥\"]}]',0,44,'2026-09-27 10:04:05'),(361,'aarati','आरती','katharanatha-aarata','केदारनाथ आरती','public/img/mantra/1778039471_image.png',NULL,'[{\"label\":\"\",\"lines\":[\"जय केदार उदार शंकर,\",\"मन भयंकर दुःख हरम।\"]},{\"label\":\"\",\"lines\":[\"गौरी गणपति स्कन्द नन्दी,\",\"श्री केदार नमाम्यहम्।\"]},{\"label\":\"\",\"lines\":[\"शैल सुन्दर अति हिमालय,\",\"शुभ मन्दिर सुन्दरम।\"]},{\"label\":\"\",\"lines\":[\"निकट मन्दाकिनी सरस्वती,\",\"जय केदार नमाम्यहम।\"]},{\"label\":\"\",\"lines\":[\"उदक कुण्ड है अधम पावन,\",\"रेतस कुण्ड मनोहरम।\"]},{\"label\":\"\",\"lines\":[\"हंस कुण्ड समीप सुन्दर,\",\"जय केदार नमाम्यहम।\"]},{\"label\":\"\",\"lines\":[\"अन्नपूरणा सह अर्पणा,\",\"काल भैरव शोभितम।\"]},{\"label\":\"\",\"lines\":[\"पंच पाण्डव द्रोपदी सह,\",\"जय केदार नमाम्यहम।\"]},{\"label\":\"\",\"lines\":[\"शिव दिगम्बर भस्मधारी,\",\"अर्द्ध चन्द्र विभूषितम।\"]},{\"label\":\"\",\"lines\":[\"शीश गंगा कण्ठ फिणिपति,\",\"जय केदार नमाम्यहम।\"]},{\"label\":\"\",\"lines\":[\"कर त्रिशूल विशाल डमरू,\",\"ज्ञान गान विशारदम।\"]},{\"label\":\"\",\"lines\":[\"मझहेश्वर तुंग ईश्वर,\",\"रुद कल्प महेश्वरम।\"]},{\"label\":\"\",\"lines\":[\"पंच धन्य विशाल आलय,\",\"जय केदार नमाम्यहम।\"]},{\"label\":\"\",\"lines\":[\"नाथ पावन हे विशालम।\",\"पुण्यप्रद हर दर्शनम।\"]},{\"label\":\"\",\"lines\":[\"जय केदार उदार शंकर,\",\"पाप ताप नमाम्यहम॥\"]}]',0,45,'2026-09-27 10:04:05'),(362,'aarati','आरती','paravata-mata-aarata','पार्वती माता आरती','public/img/mantra/1778039475_image.png',NULL,'[{\"label\":\"\",\"lines\":[\"जय पार्वती माता जय पार्वती माता।\",\"ब्रह्म सनातन देवी शुभ फल की दाता॥\",\"जय पार्वती माता...\"]},{\"label\":\"\",\"lines\":[\"अरिकुल पद्म विनाशिनि जय सेवक त्राता।\",\"जग जीवन जगदम्बा, हरिहर गुण गाता॥\",\"जय पार्वती माता...\"]},{\"label\":\"\",\"lines\":[\"सिंह को वाहन साजे, कुण्डल हैं साथा।\",\"देव वधू जस गावत, नृत्य करत ताथा॥\",\"जय पार्वती माता...\"]},{\"label\":\"\",\"lines\":[\"सतयुग रूपशील अतिसुन्दर, नाम सती कहलाता।\",\"हेमांचल घर जन्मी, सखियन संग राता॥\",\"जय पार्वती माता...\"]},{\"label\":\"\",\"lines\":[\"शुम्भ निशुम्भ विदारे, हेमांचल स्थाता।\",\"सहस्त्र भुजा तनु धरि के, चक्र लियो हाथा॥\",\"जय पार्वती माता...\"]},{\"label\":\"\",\"lines\":[\"सृष्टि रूप तुही है जननी शिवसंग रंगराता।\",\"नन्दी भृंगी बीन लही सारा जग मदमाता॥\",\"जय पार्वती माता...\"]},{\"label\":\"\",\"lines\":[\"देवन अरज करत हम चित को लाता।\",\"गावत दे दे ताली, मन में रंगराता॥\",\"जय पार्वती माता...\"]},{\"label\":\"\",\"lines\":[\"श्री प्रताप आरती मैया की, जो कोई गाता।\",\"सदासुखी नित रहता सुख सम्पत्ति पाता॥\",\"जय पार्वती माता...\"]}]',0,46,'2026-09-27 10:04:05'),(363,'aarati','आरती','kashhanaecanathara-aarata','कृष्णचन्द्र आरती','public/img/mantra/1778039479_image.png',NULL,'[{\"label\":\"\",\"lines\":[\"आरती युगल किशोर की कीजै।\",\"राधे धन न्यौछावर कीजै॥\"]},{\"label\":\"\",\"lines\":[\"रवि शशि कोटि बदन की शोभा।\",\"ताहि निरख मेरो मन लोभा॥ आरती…\"]},{\"label\":\"\",\"lines\":[\"गौर श्याम मुख निरखत रीझै।\",\"प्रभु को रूप नयन भर पीजै॥ आरती…\"]},{\"label\":\"\",\"lines\":[\"कंचन थार कपूर की बाती।\",\"हरि आये निर्मल भई छाती॥ आरती…\"]},{\"label\":\"\",\"lines\":[\"फूलन के सेज फूलन की माला।\",\"रत्न सिंहासन बैठे नन्दलाला॥ आरती…\"]},{\"label\":\"\",\"lines\":[\"मोर मुकुट कर मुरली सोहै।\",\"नटवर वेष देख मन मोहे॥ आरती…\"]},{\"label\":\"\",\"lines\":[\"आधा नील पीतपट सारी।\",\"कुंज बिहारी गिरवर धारी॥ आरती…\"]},{\"label\":\"\",\"lines\":[\"श्री पुरुषोत्तम गिरवर धारी।\",\"आरती करत सकल ब्रजनारी॥ आरती…\"]},{\"label\":\"\",\"lines\":[\"नन्दनन्दन वृषभान किशोरी।\",\"परमानन्द स्वामी अविचल जोरी॥ आरती…\"]}]',0,47,'2026-09-27 10:04:05'),(364,'aarati','आरती','gayatara-mata-aarata','गायत्री माता आरती','public/img/mantra/1778039483_image.png',NULL,'[{\"label\":\"\",\"lines\":[\"जय गायत्री माता, जयति जय गायत्री माता।\",\"सत् मारग पर हमें चलाओ, जो है सुखदाता॥\",\"जयति जय गायत्री माता...\"]},{\"label\":\"\",\"lines\":[\"आदि शक्ति तुम अलख निरञ्जन जग पालन कर्त्री।\",\"दुःख, शोक, भय, क्लेश, कलह दारिद्रय दैन्य हर्त्री॥\",\"जयति जय गायत्री माता...\"]},{\"label\":\"\",\"lines\":[\"ब्रहृ रुपिणी, प्रणत पालिनी, जगतधातृ अम्बे।\",\"भवभयहारी, जनहितकारी, सुखदा जगदम्बे॥\",\"जयति जय गायत्री माता...\"]},{\"label\":\"\",\"lines\":[\"भयहारिणि भवतारिणि अनघे, अज आनन्द राशी।\",\"अविकारी, अघहरी, अविचलित, अमले, अविनाशी॥\",\"जयति जय गायत्री माता...\"]},{\"label\":\"\",\"lines\":[\"कामधेनु सत् चित् आनन्दा, जय गंगा गीता।\",\"सविता की शाश्वती शक्ति, तुम सावित्री सीता॥\",\"जयति जय गायत्री माता...\"]},{\"label\":\"\",\"lines\":[\"ऋग्, यजु, साम, अथर्व, प्रणयिनी, प्रणव महामहिमे।\",\"कुण्डलिनी सहस्त्रार, सुषुम्ना, शोभा गुण गरिमे॥\",\"जयति जय गायत्री माता...\"]},{\"label\":\"\",\"lines\":[\"स्वाहा, स्वधा, शची, ब्रहाणी, राधा, रुद्राणी।\",\"जय सतरुपा, वाणी, विघा, कमला, कल्याणी॥\",\"जयति जय गायत्री माता...\"]},{\"label\":\"\",\"lines\":[\"जननी हम है, दीन, हीन, दुःख, दरिद्र के घेरे।\",\"यदपि कुटिल, कपटी कपूत, तऊ बालक है तेरे॥\",\"जयति जय गायत्री माता...\"]},{\"label\":\"\",\"lines\":[\"स्नेहसनी करुणामयि माता, चरण शरण दीजै।\",\"बिलख रहे हम शिशु सुत तेरे, दया दृष्टि कीजै॥\",\"जयति जय गायत्री माता...\"]},{\"label\":\"\",\"lines\":[\"काम, क्रोध, मद, लोभ, दम्भ, दुर्भाव, द्वेष हरिये।\",\"शुद्ध बुद्धि, निष्पाप हृदय, मन को पवित्र करिये॥\",\"जयति जय गायत्री माता...\"]},{\"label\":\"\",\"lines\":[\"तुम समर्थ सब भाँति तारिणी, तुष्टि, पुष्टि त्राता।\",\"सत् मार्ग पर हमें चलाओ, जो है सुखदाता॥\",\"जयति जय गायत्री माता...\"]}]',0,48,'2026-09-27 10:04:05'),(365,'aarati','आरती','ganaesha-aarata','गणेश आरती','public/img/mantra/1778039487_image.png',NULL,'[{\"label\":\"\",\"lines\":[\"सुखकर्ता दुःखहर्ता वार्ता विघ्नाची\",\"नुरवी पुरवी प्रेम कृपा जयाची\",\"सर्वांगी सुंदर उटी शेंदुराची\",\"कंठी झळके माळ मुक्ताफळाची\",\"जय देव जय देव जय मंगलमूर्ती\",\"दर्शनमात्रे मनकामना पूर्ती\",\"जयदेव जयदेव\"]},{\"label\":\"\",\"lines\":[\"रत्नखचित फरा तुज गौरीकुमरा\",\"चंदनाची उटी कुंकुमकेशरा\",\"हिरेजडित मुकुट शोभतो बरा\",\"रुणझुणती नुपुरे चरणी घागरिया\",\"जयदेव जयदेव जयमंगल मूर्ती\",\"दर्शनमात्रे मनकामना पूर्ती\",\"जयदेव जयदेव\"]},{\"label\":\"\",\"lines\":[\"लंबोदर पितांबर फणिवर बंधना\",\"सरळ सोंड वक्रतुंड त्रिनयना\",\"दास रामाचा वाट पाहे सदना\",\"संकटी पावावे निर्वाणी रक्षावे सुरवर वंदना\",\"जयदेव जयदेव\",\"जयदेव जयदेव जयमंगल मूर्ती\",\"दर्शनमात्रे मनकामना पूर्ती\",\"जयदेव जयदेव\"]}]',0,49,'2026-09-27 10:04:05'),(366,'aarati','आरती','shava-aarata-1','शिव आरती','public/img/mantra/1778039491_image.png',NULL,'[{\"label\":\"\",\"lines\":[\"हर हर हर महादेव...\"]},{\"label\":\"\",\"lines\":[\"सत्य, सनातन, सुन्दर, शिव सबके स्वामी।\",\"अविकारी अविनाशी, अज अन्तर्यामी॥\",\"हर हर हर महादेव...\"]},{\"label\":\"\",\"lines\":[\"आदि, अनन्त, अनामय, अकल, कलाधारी।\",\"अमल, अरूप, अगोचर, अविचल, अघहारी॥\",\"हर हर हर महादेव...\"]},{\"label\":\"\",\"lines\":[\"ब्रह्मा, विष्णु, महेश्वर तुम त्रिमूर्तिधारी।\",\"कर्ता, भर्ता, धर्ता, तुम ही संहारी॥\",\"हर हर हर महादेव...\"]},{\"label\":\"\",\"lines\":[\"रक्षक, भक्षक, प्रेरक, प्रिय औढरदानी।\",\"साक्षी, परम अकर्ता, कर्ता अभिमानी॥\",\"हर हर हर महादेव...\"]},{\"label\":\"\",\"lines\":[\"मणिमय-भवन निवासी, अति भोगी रागी।\",\"सदा श्मशान विहारी, योगी वैरागी॥\",\"हर हर हर महादेव...\"]},{\"label\":\"\",\"lines\":[\"छाल-कपाल, गरल-गल, मुण्डमाल व्याली।\",\"चिता भस्मतन त्रिनयन, अयनमहाकाली॥\",\"हर हर हर महादेव...\"]},{\"label\":\"\",\"lines\":[\"प्रेत-पिशाच-सुसेवित, पीत जटाधारी।\",\"विवसन विकट रूपधर, रुद्र प्रलयकारी॥\",\"हर हर हर महादेव...\"]},{\"label\":\"\",\"lines\":[\"शुभ्र-सौम्य, सुरसरिधर, शशिधर, सुखकारी।\",\"अतिकमनीय, शान्तिकर, शिवमुनि मन-हारी॥\",\"हर हर हर महादेव...\"]},{\"label\":\"\",\"lines\":[\"निर्गुण, सगुण, निरञ्जन, जगमय नित्य प्रभो।\",\"कालरूप केवल हर! कालातीत विभो॥\",\"हर हर हर महादेव...\"]},{\"label\":\"\",\"lines\":[\"सत्‌, चित्‌, आनन्द, रसमय, करुणामय धाता।\",\"प्रेम-सुधा-निधि प्रियतम, अखिल विश्व त्राता॥\",\"हर हर हर महादेव...\"]},{\"label\":\"\",\"lines\":[\"हम अतिदीन, दयामय! चरण-शरण दीजै।\",\"सब विधि निर्मल मति कर, अपना कर लीजै॥\",\"हर हर हर महादेव...\"]}]',0,50,'2026-09-27 10:04:05'),(367,'aarati','आरती','bkabhara-aarata','बाँकेबिहारी आरती','public/img/mantra/1778039495_image.png',NULL,'[{\"label\":\"\",\"lines\":[\"श्री बाँकेबिहारी तेरी आरती गाऊँ।\",\"कुन्जबिहारी तेरी आरती गाऊँ।\",\"श्री श्यामसुन्दर तेरी आरती गाऊँ।\",\"श्री बाँकेबिहारी तेरी आरती गाऊँ॥\"]},{\"label\":\"\",\"lines\":[\"मोर मुकुट प्रभु शीश पे सोहे।\",\"प्यारी बंशी मेरो मन मोहे।\",\"देखि छवि बलिहारी जाऊँ।\",\"श्री बाँकेबिहारी तेरी आरती गाऊँ॥\"]},{\"label\":\"\",\"lines\":[\"चरणों से निकली गंगा प्यारी।\",\"जिसने सारी दुनिया तारी।\",\"मैं उन चरणों के दर्शन पाऊँ।\",\"श्री बाँकेबिहारी तेरी आरती गाऊँ॥\"]},{\"label\":\"\",\"lines\":[\"दास अनाथ के नाथ आप हो।\",\"दुःख सुख जीवन प्यारे साथ हो।\",\"हरि चरणों में शीश नवाऊँ।\",\"श्री बाँकेबिहारी तेरी आरती गाऊँ॥\"]},{\"label\":\"\",\"lines\":[\"श्री हरि दास के प्यारे तुम हो।\",\"मेरे मोहन जीवन धन हो।\",\"देखि युगल छवि बलि-बलि जाऊँ।\",\"श्री बाँकेबिहारी तेरी आरती गाऊँ॥\"]},{\"label\":\"\",\"lines\":[\"आरती गाऊँ प्यारे तुमको रिझाऊँ।\",\"हे गिरिधर तेरी आरती गाऊँ।\",\"श्री श्यामसुन्दर तेरी आरती गाऊँ।\",\"श्री बाँकेबिहारी तेरी आरती गाऊँ॥\"]}]',0,51,'2026-09-27 10:04:05'),(368,'aarati','आरती','vashhanae-thava-aarata','वैष्णो देवी आरती','public/img/mantra/1778039504_image.png',NULL,'[{\"label\":\"\",\"lines\":[\"जय वैष्णवी माता, मैया जय वैष्णवी माता।\",\"हाथ जोड़ तेरे आगे, आरती मैं गाता॥\"]},{\"label\":\"\",\"lines\":[\"शीश पे छत्र विराजे, मूरतिया प्यारी।\",\"गंगा बहती चरनन, ज्योति जगे न्यारी॥\"]},{\"label\":\"\",\"lines\":[\"ब्रह्मा वेद पढ़े नित द्वारे, शंकर ध्यान धरे।\",\"सेवक चंवर डुलावत, नारद नृत्य करे॥\"]},{\"label\":\"\",\"lines\":[\"सुन्दर गुफा तुम्हारी, मन को अति भावे।\",\"बार-बार देखन को, ऐ माँ मन चावे॥\"]},{\"label\":\"\",\"lines\":[\"भवन पे झण्डे झूलें, घंटा ध्वनि बाजे।\",\"ऊँचा पर्वत तेरा, माता प्रिय लागे॥\"]},{\"label\":\"\",\"lines\":[\"पान सुपारी ध्वजा नारियल, भेंट पुष्प मेवा।\",\"दास खड़े चरणों में, दर्शन दो देवा॥\"]},{\"label\":\"\",\"lines\":[\"जो जन निश्चय करके, द्वार तेरे आवे।\",\"उसकी इच्छा पूरण, माता हो जावे॥\"]},{\"label\":\"\",\"lines\":[\"इतनी स्तुति निश-दिन, जो नर भी गावे।\",\"कहते सेवक ध्यानू, सुख सम्पत्ति पावे॥\"]}]',0,52,'2026-09-27 10:04:05'),(369,'aarati','आरती','bhagavatha-gata-aarata','भगवद्‍ गीता आरती','public/img/mantra/1778039509_image.png',NULL,'[{\"label\":\"\",\"lines\":[\"जय भगवद् गीते, जय भगवद् गीते।\",\"हरि-हिय-कमल-विहारिणि, सुन्दर सुपुनीते॥\"]},{\"label\":\"\",\"lines\":[\"कर्म-सुमर्म-प्रकाशिनि, कामासक्तिहरा।\",\"तत्त्वज्ञान-विकाशिनि, विद्या ब्रह्म परा॥\",\"जय भगवद् गीते...\"]},{\"label\":\"\",\"lines\":[\"निश्चल-भक्ति-विधायिनि, निर्मल मलहारी।\",\"शरण-सहस्य-प्रदायिनि, सब विधि सुखकारी॥\",\"जय भगवद् गीते...\"]},{\"label\":\"\",\"lines\":[\"राग-द्वेष-विदारिणि, कारिणि मोद सदा।\",\"भव-भय-हारिणि, तारिणि परमानन्दप्रदा॥\",\"जय भगवद् गीते...\"]},{\"label\":\"\",\"lines\":[\"आसुर-भाव-विनाशिनि, नाशिनि तम रजनी।\",\"दैवी सद् गुणदायिनि, हरि-रसिका सजनी॥\",\"जय भगवद् गीते...\"]},{\"label\":\"\",\"lines\":[\"समता, त्याग सिखावनि, हरि-मुख की बानी।\",\"सकल शास्त्र की स्वामिनी, श्रुतियों की रानी॥\",\"जय भगवद् गीते...\"]},{\"label\":\"\",\"lines\":[\"दया-सुधा बरसावनि, मातु! कृपा कीजै।\",\"हरिपद-प्रेम दान कर, अपनो कर लीजै॥\",\"जय भगवद् गीते...\"]},{\"label\":\"\",\"lines\":[\"जय भगवद् गीते, जय भगवद् गीते।\",\"हरि-हिय-कमल-विहारिणि, सुन्दर सुपुनीते॥\"]}]',0,53,'2026-09-27 10:04:05'),(370,'chalisa','चालीसा','hanamana-calsa','हनुमान चालीसा','public/img/mantra/1778040202_image.png',NULL,'[{\"label\":\"॥दोहा॥\",\"lines\":[\"श्रीगुरु चरन सरोज रज, निज मनु मुकुरु सुधारि।\",\"बरनउँ रघुबर बिमल जसु, जो दायकु फल चारि॥\",\"बुद्धिहीन तनु जानि के, सुमिरौं पवन-कुमार। \",\"बल बुद्धि विद्या देहु मोहिं, हरहु कलेस बिकार॥\"]},{\"label\":\"॥चौपाई॥\",\"lines\":[\"जय हनुमान ज्ञान गुनसागर।\",\"जय कपीस तिहुँलोक उजागर॥\"]},{\"label\":\"\",\"lines\":[\"रामदूत अतुलित बलधामा।\",\"अञ्जनि-पुत्र पवनसुत नामा॥\"]},{\"label\":\"\",\"lines\":[\"महाबीर बिक्रम बजरंगी।\",\"कुमति निवार सुमति के संगी॥\"]},{\"label\":\"\",\"lines\":[\"कञ्चन बरन बिराज सुबेसा।\",\"कानन कुण्डल कुञ्चित केसा॥\"]},{\"label\":\"\",\"lines\":[\"हाथ बज्र औ ध्वजा बिराजै।\",\"काँधे मूँज जनेउ साजै॥\"]},{\"label\":\"\",\"lines\":[\"सङ्कर सुवन केसरी नन्दन।\",\"तेज प्रताप महा जग वन्दन॥\"]},{\"label\":\"\",\"lines\":[\"विद्यावान गुणी अति चातुर।\",\"राम काज करिबे को आतुर॥\"]},{\"label\":\"\",\"lines\":[\"प्रभु चरित्र सुनिबे को रसिया।\",\"राम लखन सीता मन बसिया॥\"]},{\"label\":\"\",\"lines\":[\"सूक्ष्म रूप धरि सियहिं दिखावा।\",\"बिकट रूप धरि लङ्क जरावा॥\"]},{\"label\":\"\",\"lines\":[\"भीम रूप धरि असुर सँहारे।\",\"रामचन्द्र के काज सँवारे॥\"]},{\"label\":\"\",\"lines\":[\"लाय सञ्जीवन लखन जियाये।\",\"श्रीरघुवीर हरषि उर लाये॥\"]},{\"label\":\"\",\"lines\":[\"रघुपति कीह्नीं बहुत बड़ाई।\",\"तुम मम प्रिय भरतहिं सम भाई॥\"]},{\"label\":\"\",\"lines\":[\"सहस बदन तुम्हरो जस गावैं।\",\"अस कहि श्रीपति कण्ठ लगावैं॥\"]},{\"label\":\"\",\"lines\":[\"सनकादिक ब्रह्मादि मुनीसा।\",\"नारद सारद सहित अहीसा॥\"]},{\"label\":\"\",\"lines\":[\"यम कुबेर दिगपाल जहाँ ते।\",\"कवि कोविद कहि सके कहाँ ते॥\"]},{\"label\":\"\",\"lines\":[\"तुम उपकार सुग्रीवहिं कीह्ना।\",\"राम मिलाय राज पद दीह्ना॥\"]},{\"label\":\"\",\"lines\":[\"तुम्हरो मन्त्र बिभीषन माना।\",\"लंकेस्वर भए सब जग जाना॥\"]},{\"label\":\"\",\"lines\":[\"युग सहस्र योजन पर भानु।\",\"लील्यो ताहि मधुर फल जानू॥\"]},{\"label\":\"\",\"lines\":[\"प्रभु मुद्रिका मेलि मुख माहीं।\",\"जलधि लाँघि गये अचरज नाहीं॥\"]},{\"label\":\"\",\"lines\":[\"दुर्गम काज जगत के जेते।\",\"सुगम अनुग्रह तुम्हरे तेते॥\"]},{\"label\":\"\",\"lines\":[\"राम दुवारे तुम रखवारे।\",\"होत न आज्ञा बिनु पैसारे॥\"]},{\"label\":\"\",\"lines\":[\"सब सुख लहै तुम्हारी सरना।\",\"तुम रक्षक काहू को डरना॥\"]},{\"label\":\"\",\"lines\":[\"आपन तेज सम्हारो आपै।\",\"तीनों लोक हाँक तें काँपै॥\"]},{\"label\":\"\",\"lines\":[\"भूत पिसाच निकट नहिं आवै।\",\"महाबीर जब नाम सुनावै॥\"]},{\"label\":\"\",\"lines\":[\"नाशै रोग हरै सब पीरा।\",\"जपत निरन्तर हनुमत बीरा॥\"]},{\"label\":\"\",\"lines\":[\"संकट तें हनुमान छुड़ावै।\",\"मन क्रम बचन ध्यान जो लावै॥\"]},{\"label\":\"\",\"lines\":[\"सब पर राम तपस्वी राजा।\",\"तिनके काज सकल तुम साजा॥\"]},{\"label\":\"\",\"lines\":[\"और मनोरथ जो कोई लावै।\",\"सोई अमित जीवन फल पावै॥\"]},{\"label\":\"\",\"lines\":[\"चारों जुग परताप तुम्हारा।\",\"है परसिद्ध जगत उजियारा॥\"]},{\"label\":\"\",\"lines\":[\"साधु सन्त के तुम रखवारे।\",\"असुर निकन्दन राम दुलारे॥\"]},{\"label\":\"\",\"lines\":[\"अष्ट सिद्धि नौ निधि के दाता।\",\"अस बर दीन जानकी माता॥\"]},{\"label\":\"\",\"lines\":[\"राम रसायन तुम्हरे पासा।\",\"सदा रहो रघुपति के दासा॥\"]},{\"label\":\"\",\"lines\":[\"तुम्हरे भजन राम को पावै।\",\"जन्म जन्म के दुख बिसरावै॥\"]},{\"label\":\"\",\"lines\":[\"अन्त काल रघुबर पुर जाई।\",\"जहाँ जन्म हरि भक्त कहाई॥\"]},{\"label\":\"\",\"lines\":[\"और देवता चित्त न धरई।\",\"हनुमत सेइ सर्ब सुख करई॥\"]},{\"label\":\"\",\"lines\":[\"संकट कटै मिटै सब पीरा।\",\"जो सुमिरै हनुमत बलबीरा॥\"]},{\"label\":\"\",\"lines\":[\"जय जय जय हनुमान गोसाईं।\",\"कृपा करहु गुरुदेव की नाईं॥\"]},{\"label\":\"\",\"lines\":[\"जो शत बार पाठ कर कोई।\",\"छूटहिं बन्दि महा सुख होई॥\"]},{\"label\":\"\",\"lines\":[\"जो यह पढ़ै हनुमान चालीसा।\",\"होय सिद्ध साखी गौरीसा॥\"]},{\"label\":\"\",\"lines\":[\"तुलसीदास सदा हरि